import{_ as o,a0 as r,w as l,s as u,I as i,x as e,a1 as s,A as a,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse(`{"title":"如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150603 Here's How to Install the Beautiful Arc GTK+ Flat Theme on Linux","title":"如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc","tag":"201506","desc":""},"relativePath":"201506/20150603 Here's How to Install the Beautiful Arc GTK+ Flat Theme on Linux.md","filePath":"[post].md"}`),m={name:"201506/20150603 Here's How to Install the Beautiful Arc GTK+ Flat Theme on Linux.md"};function T(d,t,g,f,x,h){const n=r("Link");return l(),u("div",null,[t[16]||(t[16]=i("h1",{id:"如何在-linux-中安裝漂亮的-gtk-扁平化主題-arc",tabindex:"-1"},[e("如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc "),i("a",{class:"header-anchor",href:"#如何在-linux-中安裝漂亮的-gtk-扁平化主題-arc","aria-label":"Permalink to “如何在 Linux 中安裝漂亮的 GTK+ 扁平化主題 Arc”"},"​")],-1)),i("p",null,[i("strong",null,[t[1]||(t[1]=e("今天我們將向你介紹最新發布的GTK+主題，它擁有透明和扁平元素，並且與多個桌面環境和Linux發行版兼容。",-1)),s(n,{href:"https://github.com/horst3180/Arc-theme"},{default:a(()=>[...t[0]||(t[0]=[e("這個主題叫Arc",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))])]),t[17]||(t[17]=p(`<p>開始講細節之前，我建議你快速瀏覽一下下面的圖，這樣你有會對這個主題就會有一個基本的概念了。同樣你應該知道它目前可以工作在GTK+ 2.x、GTK+ 3.x、GNOME-Shell、 Budgie、 Unity和Pantheon用户界面，它們都使用了GNOME 體系。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Here-s-How-to-Install-the-Beautiful-Arc-GTK-plus-Flat-Theme-on-Linux-483143-2.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Here-s-How-to-Install-the-Beautiful-Arc-GTK-plus-Flat-Theme-on-Linux-483143-3.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/news2/Here-s-How-to-Install-the-Beautiful-Arc-GTK-plus-Flat-Theme-on-Linux-483143-4.jpg" alt=""></p><p>同樣、Arc主題的開發者告訴我們它已經成功地在Ubuntu 15.04（Vivid Vervet）、 Arch Linux、 elementary OS 0.3 Freya、 Fedora 21、 Fedora 22、 Debian GNU/Linux 8.0 (Jessie)、 Debian Testing、 Debian Unstable、 openSUSE 13.2、 openSUSE Tumbleweed和Gentoo測試過了。</p><h3 id="要求和安裝指導" tabindex="-1">要求和安裝指導 <a class="header-anchor" href="#要求和安裝指導" aria-label="Permalink to “要求和安裝指導”">​</a></h3><p>要構建Arc主題，你需要先安裝一些包，比如autoconf、 automake、 pkg-config (對於Fedora則是pkgconfig)、基於Debian/Ubuntu-based發行版的libgtk-3-dev或者基於RPM的gtk3-devel、 git、 gtk2-engines-pixbuf和gtk-engine-murrine (對於Fedora則是gtk-murrine-engine)。</p><p>Arc主題還沒有二進制包，因此你需要從git倉庫中取下最新的源碼並編譯。這樣，打開終端並運行下面的命令，一行行地輸入，並在每行的末尾按下回車鍵並等待上一步完成來繼續下一步。</p><pre><code>git clone https://github.com/horst3180/arc-theme --depth 1 &amp;&amp; cd arc-theme
git fetch --tags
git checkout $(git describe --tags \`git rev-list --tags --max-count=1\`)
./autogen.sh --prefix=/usr
sudo make install
</code></pre><p>就是這樣！此時你已經在你的GNU/Linux發行版中安裝了Arc主題，如果你使用GNOME可以使用GONME Tweak工具，如果你使用Ubuntu的Unity可以使用Unity Tweak工具來激活主題。玩得開心但不要忘了在下面的評論欄裏留下你的截圖。</p><hr>`,11)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),s(n,{href:"http://news.softpedia.com/news/Here-s-How-to-Install-the-Beautiful-Arc-GTK-plus-Flat-Theme-on-Linux-483143.shtml"},{default:a(()=>[...t[3]||(t[3]=[e("http://news.softpedia.com/news/Here-s-How-to-Install-the-Beautiful-Arc-GTK-plus-Flat-Theme-on-Linux-483143.shtml",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=e("作者：",-1)),s(n,{href:"http://news.softpedia.com/editors/browse/marius-nestor"},{default:a(()=>[...t[5]||(t[5]=[e("Marius Nestor",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),s(n,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[7]||(t[7]=[e("caroline",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),s(n,{href:"https://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const G=o(m,[["render",T]]);export{A as __pageData,G as default};
